//! Canonical INPUT/BUTTON disabled reflection preserves native state.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://control-disabled.test/send><input id=area name=q required><input id=input type=submit name=i value=I><button id=button type=submit name=b value=B>Send</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://control-disabled.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn control_disabled_canonical_hook_free_truthiness_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get disabled'||a.set.name!=='set disabled'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'disabled')||x.disabled!==false)throw 'canonical';var calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('bool'),BigInt(1),author]){a.set.call(x,value);if(x.disabled!==true||x.getAttributeNS(null,'disabled')!==''||calls)throw 'true';}for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.disabled!==false||x.hasAttribute('disabled')||calls)throw 'false';}a.set.call(x);if(x.disabled!==false||calls)throw 'missing argument';}");}
#[test]
fn control_disabled_inert_exact_namespace_raw_presence_and_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['input','button']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','disabled','foreign');x.setAttributeNS(null,'DISABLED','upper');if(x.disabled!==false)throw 'namespace';x.setAttributeNS(null,'disabled','\ud800');if(x.disabled!==true)throw 'raw presence';var a=x.getAttributeNodeNS(null,'disabled'),copy=x.cloneNode(false);copy.disabled=false;if(copy.disabled!==false||x.disabled!==true||a.value!=='\ud800'||copy.getAttributeNS('urn:foreign','disabled')!=='foreign')throw 'copy';x.disabled=true;if(x.getAttributeNodeNS(null,'disabled')!==a||a.value!=='')throw 'identity';}"#);}
#[test]
fn control_disabled_brands_saved_prototype_and_native_observation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'disabled');for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,true);throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}x.setAttribute('disabled','legacy');var old=x.getAttributeNodeNS(null,'disabled'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.disabled=false;var records=watch.takeRecords();if(x.disabled!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='disabled')throw 'remove observation';var calls=0;x.disabled={toString:function(){calls++;throw 'coercion';},valueOf:function(){calls++;throw 'coercion';}};records=watch.takeRecords();if(calls||x.disabled!==true||x.getAttributeNS(null,'disabled')!==''||records.length!==1||records[0].oldValue!==null)throw 'hook free observation';watch.disconnect();Object.defineProperty(P,'disabled',{get:function(){return 'author';},configurable:true});a.set.call(x,false);if(x.disabled!=='author'||a.get.call(x)!==false)throw 'saved authority';Object.defineProperty(P,'disabled',a);}");}
#[test]
fn control_disabled_captured_origin_denies_then_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var input=document.getElementById('input'),button=document.getElementById('button'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'disabled'),b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'disabled');if(a.get.call(input)!==false||b.get.call(button)!==false)throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-control-disabled.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(input);","b.get.call(button);","a.set.call(input,true);","b.set.call(button,true);"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://control-disabled.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"a.set.call(input,true);b.set.call(button,true);if(input.disabled!==true||button.disabled!==true)throw 'fresh recovery';");}
#[test]
fn control_disabled_bounded_atomic_refusal_and_zero_copy_getter(){for id in ["input","button"]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("var x=document.getElementById('{id}');x;"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_disabled_set(object,&Value::Bool(true))}else{bridge.button_disabled_set(object,&Value::Bool(true))};assert!(result.is_err(),"id {id} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.disabled=true;if(x.disabled!==true)throw 'fresh recovery';");}for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let Value::Host(object)=p.runtime.execute(&format!("document.getElementById('{id}');"),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_disabled_get(object)}else{bridge.button_disabled_get(object)};assert!(result.is_err());p.state.execution_deadline=None;p.begin_job();p.state.copy_work=0;let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if id=="input"{bridge.input_disabled_get(object)}else{bridge.button_disabled_get(object)};assert!(matches!(result,Ok(Value::Bool(false))));}}}
#[test]
fn control_disabled_attribute_writers_preserve_dirty_editor(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.disabled=true;var attribute=x.getAttributeNodeNS(null,'disabled'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('disabled','false');","x.setAttributeNS(null,'disabled','false');","attribute.value='false';","attribute.nodeValue='false';","attribute.textContent='false';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.disabled=true;watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.disabled!==true||x.getAttributeNodeNS(null,'disabled')!==attribute||records.length!==1||records[0].oldValue!==''||records[0].attributeName!=='disabled'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value,c.required),(3,1,2,true,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('disabled');replacement.value='\ud800';x.setAttributeNodeNS(replacement);if(x.disabled!==true||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'raw replacement';x.disabled=false;if(x.disabled!==false||replacement.ownerElement!==null)throw 'remove';"#);}}

#[test]
fn control_disabled_native_submitters_required_exclusion_and_state_recover(){let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let area=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap();let location=crate::navigation::address("https://control-disabled.test/source",&crate::navigation::Location::home()).unwrap();assert!(f.submit_request(&d,owner,None,&location,&location).is_err());run(&mut d,&mut f,&mut p,"document.getElementById('area').disabled=true;");assert!(f.controls[&area].disabled);let request=f.submit_request(&d,owner,None,&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert!(body.is_empty());run(&mut d,&mut f,&mut p,"document.getElementById('area').disabled=false;document.getElementById('area').value='Seed';");let before=f.controls.iter().map(|(&n,c)|(n,c.value.text(),c.required,c.checked,c.owner,c.dirty_value)).collect::<Vec<_>>();for id in ["input","button"]{let control=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();assert!(f.submit_request(&d,owner,Some(control),&location,&location).is_ok());run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');x.disabled=true;"));assert!(f.controls[&control].disabled);assert!(f.submit_request(&d,owner,Some(control),&location,&location).unwrap_err().contains("not available"));p.begin_job();run(&mut d,&mut f,&mut p,"x.disabled=false;");let request=f.submit_request(&d,owner,Some(control),&location,&location).unwrap();let crate::http::Request::FormPost{body,..}=request.request else{panic!("POST")};assert_eq!(body,if id=="input"{b"q=Seed&i=I".as_slice()}else{b"q=Seed&b=B".as_slice()});}assert_eq!(f.controls.iter().map(|(&n,c)|(n,c.value.text(),c.required,c.checked,c.owner,c.dirty_value)).collect::<Vec<_>>(),before);}
#[test]
fn control_disabled_fieldset_effective_state_is_separate_from_own_presence(){for kind in ["input","button"]{let markup=if kind=="input"{"<form><fieldset disabled><legend><input id=exempt value=Seed></legend><input id=blocked value=Other></fieldset></form>"}else{"<form><fieldset disabled><legend><button id=exempt type=button value=Seed>Seed</button></legend><button id=blocked type=button value=Other>Other</button></fieldset></form>"};let mut d=crate::html::parse(markup);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let exempt=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("exempt")).unwrap();let blocked=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("blocked")).unwrap();assert!(!f.controls[&exempt].disabled&&f.controls[&blocked].disabled);run(&mut d,&mut f,&mut p,"var a=document.getElementById('exempt'),b=document.getElementById('blocked');if(a.disabled||b.disabled)throw 'own presence only';b.disabled=true;b.disabled=false;a.disabled=true;");assert!(f.controls[&exempt].disabled&&f.controls[&blocked].disabled);run(&mut d,&mut f,&mut p,"a.disabled=false;if(a.disabled||b.disabled)throw 'fieldset own reflection';");assert!(!f.controls[&exempt].disabled&&f.controls[&blocked].disabled);assert_eq!(f.controls[&exempt].value.text(),"Seed");assert_eq!(f.controls[&blocked].value.text(),"Other");}}
